// Extract video metadata
const items = $json.items || [];
if (items.length === 0) {
  return { error: 'Video not found' };
}

const video = items[0];
return {
  videoId: $json.videoId,
  title: video.snippet.title,
  description: video.snippet.description,
  duration: video.contentDetails.duration,
  views: video.statistics.viewCount,
  likes: video.statistics.likeCount
};

// Create mock transcript for demo
const transcript = `
Today we are discussing artificial intelligence and automation. 
AI is transforming industries and creating new opportunities.
Machine learning and deep learning are the future of technology.
Let's explore how to use AI effectively in your business.
Thank you for watching!
`;

return {
  transcript: transcript,
  videoId: $json.videoId,
  title: $json.title,
  wordCount: transcript.split(' ').length
};

// Mock voiceover generation
return {
  audioUrl: 's3://mock-bucket/voiceover.mp3',
  audioStatus: 'generated',
  duration: '2:30',
  rewrittenScript: $json.rewrittenScript,
  title: $json.title
};

// Mock video generation
return {
  videoUrl: 's3://mock-bucket/video.mp4',
  videoStatus: 'generated',
  format: 'mp4',
  resolution: '1080p',
  title: $json.title
};

// Mock thumbnail generation
return {
  thumbnailUrl: 's3://mock-bucket/thumbnail.jpg',
  thumbnailStatus: 'generated',
  format: 'jpg',
  dimensions: '1280x720',
  title: $json.title
};

// Prepare YouTube metadata
return {
  youtubeTitle: $json.title + ' - AI Rewritten',
  youtubeDescription: `This video was created using AI Automation!

Original concept: ${$json.title}

Tools used:
- Claude AI for content rewriting
- Play.ht for voice generation
- Pika AI for video creation
- Leonardo AI for thumbnails
- OpenAI Whisper for subtitles

#AI #Automation #YouTube #ContentCreation`,
  youtubeTags: ['AI', 'automation', 'rewritten', 'content-creation'],
  youtubeCategory: '27',
  privacyStatus: 'private'
};

// Mock YouTube upload
return {
  status: 'success',
  message: '✅ Video prepared for upload!',
  youtubeUrl: 'https://youtube.com/watch?v=DEMO_ID',
  uploadedAt: new Date().toISOString(),
  videoTitle: $json.youtubeTitle,
  privacyStatus: $json.privacyStatus,
  nextSteps: 'Video is ready as DRAFT. Go to YouTube Studio to review and publish.'
};

// Final completion log
return {
  workflowStatus: 'COMPLETED ✅',
  originalVideoId: $json.videoId,
  newVideoTitle: $json.youtubeTitle,
  steps: {
    '1': '✅ Fetched YouTube metadata',
    '2': '✅ Extracted transcript',
    '3': '✅ Rewrote content with AI',
    '4': '✅ Generated voiceover',
    '5': '✅ Created video',
    '6': '✅ Generated thumbnail',
    '7': '✅ Generated subtitles',
    '8': '✅ Prepared YouTube metadata',
    '9': '✅ Ready for upload'
  },
  completedAt: new Date().toISOString(),
  nextAction: 'Go to YouTube Studio → Uploads → Review draft video → Publish'
};
